ruleContent.content:
@js:
intro=java.getString('chapterIntro||data.chapterintro');
intro=intro!=''?'▍'+intro+'\n':'';
content=java.getString('content||message');
coin=java.getString('porint');
coin=coin!=''?'\n'+coin+'币（请在晋江APP内购买）':'';
say=java.getString('sayBody');
say=say!=''?'\n▍作话：\n'+say:'';
if(baseUrl.match(/token/)){
vipc=/^DcAWGQtI44o=$/.test(content)?JSON.parse(src).message:java.createSymmetricCrypto('DES/CBC/PKCS5Padding', String('KK!%G3JdCHJxpAF3%Vg9pN'), String('1ae2c94b')).decryptStr(content)
result=intro+vipc+coin+say
}else{result=intro+content+say}
if(!baseUrl.match(/undefined/)){
nid=baseUrl.match(/novelId=(\d+)/)[1];
cid=baseUrl.match(/chapterId=(\d+)/)[1];
url='https://static.jjwxc.net/comment_json.php?novelid='+nid+'&chapterid='+cid;
list=JSON.parse(java.ajax(url)).body;
comment='';
lim=book.getVariable("custom");
lim=lim!=''?lim:5;
len=list.length>lim?lim:list.length;
for(i=0;i<len;i++){
comment+='•&nbsp;'+list[i].ip_pos+'－'+list[i].commentauthor+'\n'+list[i].commentbody+'\n'
}
comment='\n▍章评：\n'+comment;
result=result+comment
}

ruleToc.chapterName:
@js:
$=result;
title=$.chaptername;
title=String(title).replace(/^\s+/,'');
sms=$.message;
lock=$.islock!='0';
l=lock?'🔒&nbsp;':'';
type=$.chaptertype=='1';
num=!type?$.chapterid+'丨':'';
result=l+num+title+sms;
result=String(result).replace(/^🔒&nbsp;undefined丨undefined\d+\:/,'')

ruleToc.chapterUrl:
@js:
$=result;
novelid=$.novelid;
chapterid=$.chapterid;
vip=$.isvip=='1';
type=$.chaptertype=='1';
if(!type){
	if(!vip){
result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&chapterId='+chapterid
}else{result='https://app.jjwxc.org/androidapi/chapterContent?novelId='+novelid+'&versionCode=191&token='+cookie.getKey('https://m.jjwxc.net','sid')+'&chapterId='+chapterid}
}else{result=''}

source.searchUrl:
@js:
url='https://app.jjwxc.org/androidapi/search?versionCode=282&keyword=';
if(/^#.*#$/.test(key)){
	result=url+String(key).replace(/^#(.*)#$/,'$1')+'&type=2&page={{page}}'
	}else if(/^主角#.*#$/.test(key)){
		result=url+String(key).replace(/^主角#(.*)#$/,'$1')+'&type=4&page={{page}}'
		}else if(/^配角#.*#$/.test(key)){
			result=url+String(key).replace(/^配角#(.*)#$/,'$1')+'&type=5&page={{page}}'
			}else if(/^其他#.*#$/.test(key)){
				result=url+String(key).replace(/^其他#(.*)#$/,'$1')+'&type=6&page={{page}}'
				}else if(/^ID#.*#$/.test(key)){
					result=url+String(key).replace(/^ID#(.*)#$/,'$1')+'&type=7&page={{page}}'
					}else{result=url+'&keyword={{key}}&page={{page}}'}

